package com.aadil.ecommerce.exceptions;import com.aadil.ecommerce.responses.APIResponse;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import javax.naming.AuthenticationException;import java.time.LocalDateTime;import java.util.HashMap;import java.util.Map;@RestControllerAdvicepublic class GlobalExceptionHandler {    @ExceptionHandler(RuntimeException.class)    public ResponseEntity<APIResponse<Void>> handleRuntimeExceptions (){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage("An unexpected error has occurred");        apiResponse.setCode(500);        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.INTERNAL_SERVER_ERROR);    }    @ExceptionHandler (MethodArgumentNotValidException.class)    public ResponseEntity<APIResponse<Map<String,String>>> handlesMethodArgumentNotValid (MethodArgumentNotValidException methodArgumentNotValidException){        Map<String,String> errors = new HashMap<>();        methodArgumentNotValidException.getBindingResult().getFieldErrors().                forEach(fieldError -> errors.put(fieldError.getField(), fieldError.getDefaultMessage()));        APIResponse<Map<String, String>> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage("Validation Failed");        apiResponse.setCode(400);        apiResponse.setData(errors);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.BAD_REQUEST);    }    @ExceptionHandler(UserAlreadyExistsException.class)    public ResponseEntity<APIResponse<Void>> handlesAlreadyExists (){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage("User already exists");        apiResponse.setCode(409);        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.CONFLICT);    }    @ExceptionHandler(AuthenticationException.class)    public ResponseEntity<APIResponse<Void>> handlesAuthenticationFailException (AuthenticationException authenticationException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(authenticationException.getMessage());        apiResponse.setCode(401);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.UNAUTHORIZED);    }    @ExceptionHandler(InvalidCredentialException.class)    public ResponseEntity<APIResponse<Void>> handlesInvalidCredentials (InvalidCredentialException invalidCredentialException){        APIResponse<Void> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setMessage(invalidCredentialException.getMessage());        apiResponse.setCode(401);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse,HttpStatus.UNAUTHORIZED);    }}